import java.util.*;

class NaiveLCA {
    private final List<List<Integer>> adj;
    private final int[] parent, depth;

    NaiveLCA(int n, int root, int[][] edges) {
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }
        parent = new int[n];
        depth = new int[n];
        // Iterative DFS to avoid stack overflow on deep/chain trees.
        Deque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{root, root, 0});  // node, par, dep
        boolean[] seen = new boolean[n];
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0], par = cur[1], dep = cur[2];
            if (seen[node]) continue;
            seen[node] = true;
            parent[node] = par;
            depth[node] = dep;
            for (int next : adj.get(node)) {
                if (!seen[next]) stack.push(new int[]{next, node, dep + 1});
            }
        }
    }

    int lca(int a, int b) {
        while (depth[a] > depth[b]) a = parent[a];
        while (depth[b] > depth[a]) b = parent[b];
        while (a != b) { a = parent[a]; b = parent[b]; }
        return a;
    }
}

