import java.util.*;

class BinaryLiftingLCA {
    private final int LOG;
    private final int[][] up;   // up[v][j] = 2^j-th ancestor of v
    private final int[] depth;
    private final List<List<Integer>> adj;

    BinaryLiftingLCA(int n, int root, int[][] edges) {
        LOG = Math.max(1, 32 - Integer.numberOfLeadingZeros(n));
        up = new int[n][LOG];
        depth = new int[n];
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(e[1]); adj.get(e[1]).add(e[0]); }

        // Iterative DFS: set depth and up[v][0] = parent (root's parent = root).
        Deque<int[]> stack = new ArrayDeque<>();
        boolean[] seen = new boolean[n];
        stack.push(new int[]{root, root, 0});
        while (!stack.isEmpty()) {
            int[] cur = stack.pop();
            int node = cur[0], par = cur[1], dep = cur[2];
            if (seen[node]) continue;
            seen[node] = true;
            up[node][0] = par;
            depth[node] = dep;
            for (int next : adj.get(node)) {
                if (!seen[next]) stack.push(new int[]{next, node, dep + 1});
            }
        }
        // Doubling: up[v][j] = up[ up[v][j-1] ][j-1].
        for (int j = 1; j < LOG; j++) {
            for (int v = 0; v < n; v++) {
                up[v][j] = up[ up[v][j - 1] ][j - 1];
            }
        }
    }

    int lca(int a, int b) {
        if (depth[a] < depth[b]) { int t = a; a = b; b = t; }
        int diff = depth[a] - depth[b];
        for (int j = 0; j < LOG; j++) {        // lift a to b's depth
            if (((diff >> j) & 1) == 1) a = up[a][j];
        }
        if (a == b) return a;                  // b was an ancestor of a
        for (int j = LOG - 1; j >= 0; j--) {   // rise while ancestors differ
            if (up[a][j] != up[b][j]) { a = up[a][j]; b = up[b][j]; }
        }
        return up[a][0];
    }
}

