import sys
from collections import defaultdict

class BinaryLiftingLCA:
    def __init__(self, n: int, root: int, edges: list[tuple[int, int]]) -> None:
        self.LOG = max(1, n.bit_length())
        self.up = [[0] * self.LOG for _ in range(n)]  # up[v][j] = 2^j-th ancestor
        self.depth = [0] * n
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Iterative DFS: depth and up[v][0] = parent (root's parent = root).
        seen = [False] * n
        stack = [(root, root, 0)]
        while stack:
            node, par, dep = stack.pop()
            if seen[node]:
                continue
            seen[node] = True
            self.up[node][0] = par
            self.depth[node] = dep
            for nxt in adj[node]:
                if not seen[nxt]:
                    stack.append((nxt, node, dep + 1))

        # Doubling recurrence, column by column.
        for j in range(1, self.LOG):
            for v in range(n):
                self.up[v][j] = self.up[self.up[v][j - 1]][j - 1]

    def lca(self, a: int, b: int) -> int:
        if self.depth[a] < self.depth[b]:
            a, b = b, a
        diff = self.depth[a] - self.depth[b]
        for j in range(self.LOG):              # lift a to b's depth
            if (diff >> j) & 1:
                a = self.up[a][j]
        if a == b:                             # b was an ancestor of a
            return a
        for j in range(self.LOG - 1, -1, -1):  # rise while ancestors differ
            if self.up[a][j] != self.up[b][j]:
                a = self.up[a][j]
                b = self.up[b][j]
        return self.up[a][0]

